/**
 * Generates docs/schema-map.md from CSV exports in supabase/uploads/.
 * Run: npm run schema:map (or: tsx scripts/build-schema-map.ts)
 *
 * Required source files (exported from the Supabase SQL Editor):
 *   supabase/uploads/Supabase ueebzuleyrnsrxbowdfa Public Table Columns.csv
 *   supabase/uploads/Supabase ueebzuleyrnsrxbowdfa Foreign Key Relationships.csv
 *   supabase/uploads/Supabase Snippet List Constraints with Column Membership.csv
 *   supabase/uploads/Supabase Snippet List Public Table Policies.csv
 *
 * Output is deterministic (alphabetical) so git diffs stay clean.
 */
import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";

const UPLOADS = "supabase/uploads";
const COLUMNS_CSV = `${UPLOADS}/Supabase ueebzuleyrnsrxbowdfa Public Table Columns.csv`;
const FK_CSV = `${UPLOADS}/Supabase ueebzuleyrnsrxbowdfa Foreign Key Relationships.csv`;
const CONSTRAINTS_CSV = `${UPLOADS}/Supabase Snippet List Constraints with Column Membership.csv`;
const POLICIES_CSV = `${UPLOADS}/Supabase Snippet List Public Table Policies.csv`;
const OUT = "docs/schema-map.md";

const REQUIRED = [COLUMNS_CSV, FK_CSV, CONSTRAINTS_CSV, POLICIES_CSV];
const missing = REQUIRED.filter((f) => !existsSync(f));
if (missing.length) {
  console.error("ERROR: missing required CSV export(s):");
  for (const m of missing) console.error("  - " + m);
  console.error("\nExport them from the Supabase SQL Editor and place in supabase/uploads/.");
  console.error("See docs/schema/README.md for instructions.");
  process.exit(1);
}

// ----- tiny CSV parser (handles quoted commas/newlines) -----
function parseCSV(text: string): Record<string, string>[] {
  const lines: string[][] = [];
  let row: string[] = [];
  let cur = "";
  let inQ = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQ) {
      if (c === '"' && text[i + 1] === '"') { cur += '"'; i++; }
      else if (c === '"') inQ = false;
      else cur += c;
    } else {
      if (c === '"') inQ = true;
      else if (c === ",") { row.push(cur); cur = ""; }
      else if (c === "\n") { row.push(cur); lines.push(row); row = []; cur = ""; }
      else if (c === "\r") { /* skip */ }
      else cur += c;
    }
  }
  if (cur.length || row.length) { row.push(cur); lines.push(row); }
  const headers = lines.shift()!.map((h) => h.trim());
  return lines
    .filter((r) => r.length === headers.length && r.some((v) => v.length))
    .map((r) => Object.fromEntries(headers.map((h, i) => [h, r[i]])));
}

const norm = (v: string | undefined) => (v == null || v === "null" ? "" : v);

type Col = { name: string; data_type: string; nullable: boolean; default: string };
type FK = { column: string; foreign_table: string; foreign_column: string };
type InRef = { from_table: string; from_column: string; to_column: string };
type Constraint = { name: string; type: string; columns: string };
type Policy = { name: string; cmd: string; using: string; check: string };

const columns: Record<string, Col[]> = {};
const pk: Record<string, string[]> = {};
const uniques: Record<string, string[][]> = {};
const checks: Record<string, Constraint[]> = {};
const fksOut: Record<string, FK[]> = {};
const fksIn: Record<string, InRef[]> = {};
const policies: Record<string, Policy[]> = {};

// columns
for (const r of parseCSV(readFileSync(COLUMNS_CSV, "utf8"))) {
  if (r.table_schema !== "public") continue;
  (columns[r.table_name] ??= []).push({
    name: r.column_name,
    data_type: r.data_type,
    nullable: r.is_nullable === "YES",
    default: norm(r.column_default),
  });
}

// foreign keys + pk (from FK CSV — also has PK/UNIQUE rows)
for (const r of parseCSV(readFileSync(FK_CSV, "utf8"))) {
  const t = r.table_name;
  if (!t || t === "null") continue;
  if (r.constraint_type === "PRIMARY KEY") {
    (pk[t] ??= []).push(r.column_name);
  } else if (r.constraint_type === "FOREIGN KEY") {
    (fksOut[t] ??= []).push({
      column: r.column_name,
      foreign_table: r.foreign_table_name,
      foreign_column: r.foreign_column_name,
    });
    (fksIn[r.foreign_table_name] ??= []).push({
      from_table: t,
      from_column: r.column_name,
      to_column: r.foreign_column_name,
    });
  }
}

// constraints (UNIQUE, CHECK) from dedicated snippet
for (const r of parseCSV(readFileSync(CONSTRAINTS_CSV, "utf8"))) {
  const t = r.table_name;
  if (!t) continue;
  const type = r.constraint_type;
  const cols = norm(r.columns);
  if (type === "UNIQUE") {
    (uniques[t] ??= []).push(cols.split(",").map((s) => s.trim()).filter(Boolean));
  } else if (type === "CHECK") {
    (checks[t] ??= []).push({ name: r.constraint_name, type, columns: cols });
  } else if (type === "PRIMARY KEY" && !pk[t]) {
    pk[t] = cols.split(",").map((s) => s.trim()).filter(Boolean);
  }
}

// policies
const POLICY_WARNINGS: { table: string; policy: string; reason: string; expr: string }[] = [];
const BROKEN_PATTERNS: { pattern: RegExp; reason: string }[] = [
  { pattern: /auth\.jwt\(\)\s*->>\s*'tenant_id'/i, reason: "uses auth.jwt() ->> 'tenant_id' (claim not populated by default — policy will block all rows)" },
  { pattern: /\btrue\b\s*\)?\s*$/i, reason: "policy expression evaluates to TRUE (no tenant/user scoping)" },
];

for (const r of parseCSV(readFileSync(POLICIES_CSV, "utf8"))) {
  const t = r.table_name;
  if (!t) continue;
  const p: Policy = {
    name: r.policy_name,
    cmd: r.command,
    using: norm(r.using_expression),
    check: norm(r.check_expression),
  };
  (policies[t] ??= []).push(p);
  for (const exprLabel of [p.using, p.check]) {
    if (!exprLabel) continue;
    for (const { pattern, reason } of BROKEN_PATTERNS) {
      if (pattern.test(exprLabel)) {
        POLICY_WARNINGS.push({ table: t, policy: p.name, reason, expr: exprLabel });
      }
    }
  }
}

const allTables = Object.keys(columns).sort();

// ----- render -----
const lines: string[] = [];
lines.push(`# Schema Map`);
lines.push("");
lines.push(`Source of truth: CSV exports in \`supabase/uploads/\`.`);
lines.push(`Generated by \`scripts/build-schema-map.ts\` — **do not edit by hand**; regenerate with \`npm run schema:map\`.`);
lines.push("");
lines.push(`Totals: ${allTables.length} tables, ${Object.values(fksOut).reduce((s, a) => s + a.length, 0)} foreign keys, ${Object.values(policies).reduce((s, a) => s + a.length, 0)} RLS policies.`);
lines.push("");

lines.push(`## How to use (SQL validation checklist)`);
lines.push("");
lines.push(`Before writing any SQL against this project:`);
lines.push("");
lines.push(`1. Every table referenced exists in this document.`);
lines.push(`2. Every column referenced exists under that table.`);
lines.push(`3. Every JOIN follows a FK listed under "Foreign keys (out)" or "Referenced by (in)".`);
lines.push(`4. Review the RLS policies on each table — your query runs under them.`);
lines.push(`5. No destructive SQL (DROP / TRUNCATE / DELETE without WHERE / ALTER ... DROP) unless explicitly requested.`);
lines.push("");

// Warnings section first so it's hard to miss
lines.push(`## ⚠️ RLS policy warnings`);
lines.push("");
if (POLICY_WARNINGS.length === 0) {
  lines.push(`No broken patterns detected.`);
} else {
  lines.push(`The following policies use patterns that are likely broken and will silently return empty result sets:`);
  lines.push("");
  const sorted = [...POLICY_WARNINGS].sort((a, b) =>
    a.table.localeCompare(b.table) || a.policy.localeCompare(b.policy) || a.reason.localeCompare(b.reason)
  );
  for (const w of sorted) {
    lines.push(`- \`${w.table}\` / \`${w.policy}\` — ${w.reason}`);
    lines.push(`  - expr: \`${w.expr}\``);
  }
}
lines.push("");

// Table list
lines.push(`## Tables`);
lines.push("");
for (const t of allTables) lines.push(`- [${t}](#${t})`);
lines.push("");

function renderTable(t: string) {
  const cs = columns[t] ?? [];
  lines.push(`### ${t}`);
  const pkCols = pk[t] ?? [];
  lines.push(`- Primary key: ${pkCols.length ? pkCols.join(", ") : "(none declared)"}`);
  lines.push(`- Columns:`);
  for (const c of cs) {
    const def = c.default ? `, default ${c.default}` : "";
    lines.push(`  - ${c.name}: ${c.data_type}${c.nullable ? "" : ", not null"}${def}`);
  }
  const uq = uniques[t] ?? [];
  if (uq.length) {
    lines.push(`- Unique constraints:`);
    for (const u of uq) lines.push(`  - (${u.join(", ")})`);
  }
  const ck = checks[t] ?? [];
  if (ck.length) {
    lines.push(`- Check constraints:`);
    for (const c of ck) lines.push(`  - ${c.name}${c.columns ? ` on (${c.columns})` : ""}`);
  }
  const out = (fksOut[t] ?? []).slice().sort((a, b) => a.column.localeCompare(b.column));
  if (out.length) {
    lines.push(`- Foreign keys (out):`);
    for (const f of out) lines.push(`  - ${f.column} → ${f.foreign_table}.${f.foreign_column}`);
  }
  const inn = (fksIn[t] ?? []).slice().sort((a, b) =>
    a.from_table.localeCompare(b.from_table) || a.from_column.localeCompare(b.from_column)
  );
  if (inn.length) {
    lines.push(`- Referenced by (in):`);
    for (const f of inn) lines.push(`  - ${f.from_table}.${f.from_column} → ${f.to_column}`);
  }
  const pols = (policies[t] ?? []).slice().sort((a, b) => a.name.localeCompare(b.name));
  if (pols.length) {
    lines.push(`- RLS policies:`);
    for (const p of pols) {
      lines.push(`  - \`${p.name}\` (${p.cmd})`);
      if (p.using) lines.push(`    - USING: \`${p.using}\``);
      if (p.check) lines.push(`    - WITH CHECK: \`${p.check}\``);
    }
  } else {
    lines.push(`- RLS policies: (none recorded — table may be unprotected)`);
  }
  lines.push("");
}

lines.push(`## Table details`);
lines.push("");
for (const t of allTables) renderTable(t);

mkdirSync("docs", { recursive: true });
writeFileSync(OUT, lines.join("\n"));
console.log(`Wrote ${OUT} (${allTables.length} tables, ${POLICY_WARNINGS.length} policy warnings)`);
